package org.apache.commons.math.analysis.solvers;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.MaxIterationsExceededException;
import org.apache.commons.math.analysis.UnivariateRealFunction;
import org.apache.commons.math.exception.MaxCountExceededException;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for BisectionSolver.solve(UnivariateRealFunction, double, double, double)
 */
public class BisectionSolver_solve_TriageGen2Test {

    /**
     * Note: Based on the provided code snippet:
     * public double solve(final UnivariateRealFunction f, double min, double max, double initial)
     *         throws MaxIterationsExceededException, FunctionEvaluationException {
     *     return solve(min, max);
     * }
     *
     * The implementation provided in the prompt actually ignores 'f' and 'initial' 
     * and calls solve(min, max). This test reflects that specific implementation logic.
     */

    @Test
    public void testSolve_Success() throws MaxIterationsExceededException, FunctionEvaluationException {
        BisectionSolver solver = new BisectionSolver();
        // f(x) = x - 2. Root is at 2.0
        UnivariateRealFunction f = x -> x - 2.0;
        double min = 0.0;
        double max = 4.0;
        double initial = 1.0;

        double result = solver.solve(f, min, max, initial);

        // Given the implementation calls solve(min, max), it should find the root 2.0
        Assert.assertEquals(2.0, result, 1e-10);
    }

    @Test
    public void testSolve_WithConstructorFunction() throws MaxIterationsExceededException, FunctionEvaluationException {
        // Testing the constructor that takes a function
        UnivariateRealFunction f = x -> x - 5.0;
        BisectionSolver solver = new BisectionSolver(f);
        double min = 0.0;
        double max = 10.0;
        double initial = 3.0;

        double result = solver.solve(f, min, max, initial);

        Assert.assertEquals(5.0, result, 1e-10);
    }

    @Test(expected = MaxCountExceededException.class)
    public void testSolve_MaxIterationsExceeded() throws MaxIterationsExceededException, FunctionEvaluationException {
        BisectionSolver solver = new BisectionSolver();
        // A function that doesn't cross zero in the range or causes issues
        // However, Bisection usually requires f(min)*f(max) < 0.
        // If the implementation of solve(min, max) is called, it will throw if signs are same.
        UnivariateRealFunction f = x -> 1.0; 
        double min = 0.0;
        double max = 1.0;
        double initial = 0.5;

        solver.solve(f, min, max, initial);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testSolve_InvalidRange() throws MaxIterationsExceededException, FunctionEvaluationException {
        BisectionSolver solver = new BisectionSolver();
        UnivariateRealFunction f = x -> x - 2.0;
        // min > max is typically invalid for bisection
        double min = 5.0;
        double max = 1.0;
        double initial = 3.0;

        solver.solve(f, min, max, initial);
    }

    @Test(expected = RuntimeException.class)
    public void testSolve_FunctionEvaluationException() throws MaxIterationsExceededException, FunctionEvaluationException {
        BisectionSolver solver = new BisectionSolver();
        // A function that throws an exception during evaluation
        UnivariateRealFunction f = x -> {
            throw new RuntimeException("Evaluation error");
        };
        double min = 0.0;
        double max = 2.0;
        double initial = 1.0;

        // Since the provided implementation calls solve(min, max), 
        // if solve(min, max) uses 'f', this will trigger.
        solver.solve(f, min, max, initial);
    }
}
